namespace {
QString str(const QJsonObject& o,const QString& key){return o.value(key).isString()?o.value(key).toString():QString();}
bool digits(const QString& s,int min=1,int max=20){if(s.size()<min||s.size()>max)return false;for(auto c:s)if(c<'0'||c>'9')return false;return true;}
bool num(const QString& s,int integer=16,int fraction=2){if(s.isEmpty()||s.size()>integer+fraction+1)return false;const auto parts=s.split('.');return parts.size()<=2&&digits(parts[0],1,integer)&&(parts.size()==1||digits(parts[1],1,fraction));}
bool positive(const QString& s){return num(s)&&decimal::positive(s);}
bool signedNum(QString s){if(s.startsWith('-')||s.startsWith('+'))s.remove(0,1);return num(s,20,4);}
bool safe(const QString& s,int max=120,bool empty=false){if((s.isEmpty()&&!empty)||s.size()>max)return false;for(auto c:s)if(c.isSurrogate()||c.category()==QChar::Other_Control||c.category()==QChar::Other_Format)return false;return true;}
bool ascii(const QByteArray& s,int max=512,bool empty=false){if((s.isEmpty()&&!empty)||s.size()>max)return false;for(auto c:s)if(static_cast<unsigned char>(c)<33||static_cast<unsigned char>(c)>126)return false;return true;}
bool readSymbol(const QString& s){if(s.size()<6||s.size()>12)return false;for(auto c:s)if(!((c>='0'&&c<='9')||(c>='A'&&c<='Z')))return false;return true;}
QString stock(QString s){if(s.size()==7&&(s[0]=='A'||s[0]=='J'||s[0]=='Q'))s.remove(0,1);return readSymbol(s)?s:QString();}
QString val(const QJsonObject& o,const QString& key){auto s=str(o,key);return num(s,20,4)?decimal::normalize(s):QString();}
QByteArray copy(const SecureBuffer& b){return QByteArray(reinterpret_cast<const char*>(b.data()),qsizetype(b.size()));}
void wipe(QByteArray& b){if(!b.isEmpty()){b.detach();sodium_memzero(b.data(),size_t(b.size()));}b.clear();}
void wipe(QString& s){if(!s.isEmpty()){s.detach();sodium_memzero(s.data(),size_t(s.size())*sizeof(QChar));}s.clear();}
QByteArray digest(const QList<QByteArray>& fields){QCryptographicHash h(QCryptographicHash::Sha256);for(const auto& f:fields){quint32 n=quint32(f.size());char len[4]={char(n>>24),char(n>>16),char(n>>8),char(n)};h.addData(QByteArrayView(len,4));h.addData(f);}return h.result();}
QString randomHandle(){return QUuid::createUuid().toString(QUuid::WithoutBraces);}
QDateTime kst(QDateTime d){return d.toTimeZone(QTimeZone("Asia/Seoul"));}
QString dateOf(QDateTime d){return kst(d).toString("yyyyMMdd");}
QString dateFor(const BrokerStep& s,QDateTime d){if(s.operation==Operation::QueryOrder&&lsOrderReferenceValid(s.input.orderId))return s.input.orderId.section('_',1,1);return s.input.startTimeMs?dateOf(QDateTime::fromMSecsSinceEpoch(s.input.startTimeMs,QTimeZone::UTC)):dateOf(d);}
QString trFor(const BrokerStep& s){if(s.operation==Operation::QueryOrder&&s.variant=="receipt-open-query")return "t0425";switch(s.operation){case Operation::Authenticate:return "token";case Operation::Accounts:case Operation::Account:return "CSPAQ12200";case Operation::Holdings:return "t0424";case Operation::BuyingPower:return "CSPBQ00200";case Operation::OpenOrders:return "t0425";case Operation::History:case Operation::QueryOrder:return "CSPAQ13700";case Operation::Markets:return "t8436";case Operation::Rules:case Operation::Quote:case Operation::PriceLimits:return "t1102";case Operation::Depth:return "t8450";case Operation::Reference:return "t8412";case Operation::TradingSchedule:return "t0167";case Operation::AssetFilters:return s.variant=="managed"?"t1404":"t1405";default:return {};}}
QString variantFor(Operation op){switch(op){case Operation::Authenticate:return "token";case Operation::Accounts:return "account-discovery";case Operation::Account:return "cash-summary";case Operation::Holdings:return "positions";case Operation::BuyingPower:return "exact-cash-capacity";case Operation::OpenOrders:return "account-open";case Operation::History:case Operation::QueryOrder:return "symbol-day-detail";case Operation::Markets:return "ls-catalog";case Operation::Rules:case Operation::Quote:case Operation::PriceLimits:return "krx-price";case Operation::Depth:return "krx-depth";case Operation::Reference:return "krx-minute";case Operation::TradingSchedule:return "server-time";default:return "manual-order";}}
QString pathFor(const QString& tr){if(tr=="token")return "/oauth2/token";if(tr.startsWith("CSPAT"))return "/stock/order";if(tr=="t8436")return "/stock/etc";if(tr=="t0167")return "/etc/time-search";if(tr=="t8412")return "/stock/chart";if(tr=="t1102"||tr=="t8450"||tr=="t1404"||tr=="t1405")return "/stock/market-data";return "/stock/accno";}
QString inName(const QString& tr){return tr+(tr.startsWith("CSP")?"InBlock1":"InBlock");}
QByteArray quoted(const QString& s){auto bytes=QJsonDocument(QJsonArray{s}).toJson(QJsonDocument::Compact);return bytes.mid(1,bytes.size()-2);}
// Only fixed field names enter this encoder. Numeric lexemes are validated before
// their exact JSON representation is emitted; no QVariant/double conversion.
QByteArray encode(const QString& block,const QJsonObject& strings,const QMap<QString,QString>& numbers){QByteArray out="{"+quoted(block)+":{";bool first=true;for(auto it=strings.constBegin();it!=strings.constEnd();++it){if(!it.value().isString())return {};if(!first)out+=',';first=false;out+=quoted(it.key())+':'+quoted(it.value().toString());}for(auto it=numbers.cbegin();it!=numbers.cend();++it){if(strings.contains(it.key())||!num(it.value(),16,2))return {};if(!first)out+=',';first=false;out+=quoted(it.key())+':'+decimal::normalize(it.value()).toLatin1();}return out+"}}";}
QString tick(QString p){for(const auto& entry:QList<QPair<QString,QString>>{{"2000","1"},{"5000","5"},{"20000","10"},{"50000","50"},{"200000","100"},{"500000","500"}})if(decimal::compare(p,entry.first)<0)return entry.second;return "1000";}
QJsonObject orderJson(const OrderRecord& r){return {{"orderId",r.orderId},{"symbol",r.symbol},{"side",r.side},{"type",r.type},{"price",r.price},{"quantity",r.quantity},{"executed",r.executed},{"remaining",r.remaining},{"status",r.status},{"rawStatus",r.rawStatus},{"cancelable",r.cancelable},{"amendable",r.amendable},{"originalOrderId",r.originalOrderId},{"baseOriginalOrderId",r.baseOriginalOrderId}};}
}
LsAdapter::LsAdapter(QString environment,std::function<QDateTime()> clock):environment_(std::move(environment)),clock_(std::move(clock)){}
LsAdapter::~LsAdapter(){clearState();}
bool LsAdapter::symbolValid(const QString& s)const{return digits(s,6,6);}
bool LsAdapter::catalogSymbolValid(const QString& s)const{return readSymbol(s);}
bool LsAdapter::orderReferenceValid(const QString& s)const{return lsOrderReferenceValid(s);}
QString LsAdapter::orderReference(const QString& date,const QString& venue,const QString& number){auto s="L1_"+date+'_'+venue+'_'+number;return lsOrderReferenceValid(s)?s:QString();}
void LsAdapter::clearState()const{key_.clear();secret_.clear();token_.clear();account_.clear();assertion_.clear();tokenAge_.invalidate();lifetimeMs_=0;handle_.clear();scope_.clear();label_.clear();mutationDate_.clear();selected_=false;cursors_.clear();relations_.clear();receipts_.clear();catalog_.clear();}
void LsAdapter::clearSession(){clearState();}
bool LsAdapter::sessionReady()const{if(token_.empty()||!tokenAge_.isValid()||tokenAge_.elapsed()>=lifetimeMs_){if(!token_.empty())clearState();return false;}return true;}
QList<BrokerAccountChoice> LsAdapter::accountChoices()const{return sessionReady()&&!handle_.isEmpty()?QList<BrokerAccountChoice>{{handle_,label_}}:QList<BrokerAccountChoice>{};}
bool LsAdapter::selectBrokerAccount(const QString& handle,QString* error){if(error)error->clear();if(!sessionReady()||handle.isEmpty()||handle!=handle_){if(error)*error="인증된 LS 계좌를 선택해 주세요.";return false;}selected_=true;return true;}
QString LsAdapter::selectedAccountScope()const{return sessionReady()&&selected_?scope_:QString();}
QString LsAdapter::selectedAccountLabel()const{return sessionReady()&&selected_?label_:QString();}
bool LsAdapter::configureSession(const AccountRecord& a,const CredentialSet& c,QString* error){clearState();if(error)error->clear();auto fail=[&]{clearState();if(error)*error="LS 키·환경·계좌 확인값을 확인해 주세요.";return false;};if(a.provider!="ls"||a.environment!=environment_||environment_!="live"||a.market!="domestic_equity"||a.currency!="KRW")return fail();auto k=c.find("app_key"),s=c.find("app_secret");if(k==c.end()||s==c.end())return fail();auto kb=copy(k->second),sb=copy(s->second);auto clean=qScopeGuard([&]{wipe(kb);wipe(sb);});if(!ascii(kb)||!ascii(sb))return fail();try{key_=SecureBuffer(kb.data(),size_t(kb.size()));secret_=SecureBuffer(sb.data(),size_t(sb.size()));auto at=c.find("account_number");if(at!=c.end()&&!at->second.empty()){auto number=copy(at->second);auto guard=qScopeGuard([&]{wipe(number);});if(!ascii(number,20))return fail();assertion_=SecureBuffer(number.data(),size_t(number.size()));}}catch(...){return fail();}return true;}
QString LsAdapter::credentialIdentityFingerprint(const CredentialSet& c)const{auto at=c.find("app_key");if(at==c.end())return {};auto key=copy(at->second);auto guard=qScopeGuard([&]{wipe(key);});return digest({identityDomain(IdentityDomain::LsCredentials),environment_.toUtf8(),key}).toHex();}
BrokerPolicy LsAdapter::policy()const{BrokerPolicy p;p.provider=provider();p.displayName="LS증권";p.environment=environment_;p.exactIntentPreflight=true;p.cancelExplicitQtyBasis=ExplicitQtyBasis::Remaining;p.amendPriceOnly=true;p.placeOrderTypes={QStringLiteral("limit")};p.referenceModel=BrokerReferenceModel::TargetReceiptRoot;p.catalogSource="LS t8436";p.accountSource="CSPAQ12200";p.holdingsSource="t0424 · 현금 분류 미확인";p.buyingPowerSource="CSPBQ00200 100% 현금 + CSPAQ12200 미수불가";for(auto action:{BrokerAction::Read,BrokerAction::Place,BrokerAction::Cancel,BrokerAction::Amend})p.actions[action]={ApiAvailability::Documented,true,"조회·실전 현금 지정가 매수·검증된 양수 잔량 변경"};p.catalog={ApiAvailability::Documented,true,"KOSPI·KOSDAQ"};p.paperTrading={ApiAvailability::Documented,false,QStringLiteral("%1는 실전 연결만 지원합니다(모의 지원 종료).").arg(productName())};p.officialOrderTest={ApiAvailability::NotDocumented,false,"무체결 주문 테스트 API 미확인"};p.freshness[BrokerAction::Place]={{Operation::AssetFilters,60000,SourceTimeQuality::NotProvided,true},{Operation::Account,10000,SourceTimeQuality::NotProvided,true},{Operation::BuyingPower,10000,SourceTimeQuality::NotProvided,true},{Operation::Quote,10000,SourceTimeQuality::NotProvided,true},{Operation::Depth,10000,SourceTimeQuality::TimeOfDayOnly,true},{Operation::Reference,10000,SourceTimeQuality::FullTimestamp,true,120000},{Operation::TradingSchedule,10000,SourceTimeQuality::FullTimestamp,true}};p.freshness[BrokerAction::Amend]=p.freshness[BrokerAction::Place];p.freshness[BrokerAction::Amend].append({Operation::OpenOrders,10000,SourceTimeQuality::NotProvided,true});p.freshness[BrokerAction::Cancel]={{Operation::OpenOrders,10000,SourceTimeQuality::NotProvided,true}};return p;}
BrokerStep LsAdapter::directStep(Operation op,const OrderInput& in)const{BrokerStep s;s.operation=op;s.input=in;s.variant=variantFor(op);if(op==Operation::QueryOrder&&receipts_.contains(in.orderId)&&receipts_[in.orderId].scope==scope_&&receipts_[in.orderId].date==dateOf(clock_()))s.variant="receipt-open-query";const auto tr=trFor(s);s.minimumDelayMs=(tr=="CSPAQ12200"||tr=="CSPBQ00200"||tr=="CSPAQ13700"||tr=="t8412"||op==Operation::AssetFilters)?1100:(tr=="t0424"||tr=="t0425"||tr=="t8436")?550:350;s.authScope=op==Operation::Authenticate?BrokerAuthScope::CredentialBootstrap:op==Operation::Accounts?BrokerAuthScope::Session:BrokerAuthScope::SelectedAccount;if((op==Operation::History||op==Operation::OpenOrders)&&s.input.startTimeMs==0)s.input.startTimeMs=kst(clock_()).date().startOfDay(QTimeZone("Asia/Seoul")).toMSecsSinceEpoch();return s;}
QList<BrokerStep> LsAdapter::plan(BrokerPlanKind kind,const OrderInput& i)const{QList<BrokerStep> p;auto add=[&](Operation op){p<<directStep(op,i);};if(kind==BrokerPlanKind::Authenticate){add(Operation::Authenticate);add(Operation::Accounts);return p;}if(kind==BrokerPlanKind::Catalog){for(const auto& market:{QString("KOSPI"),QString("KOSDAQ")}){auto s=directStep(Operation::Markets,{});s.catalogMarket=market;s.allowEmptyCatalog=true;p<<s;}return p;}if(kind==BrokerPlanKind::AccountRead){add(Operation::OpenOrders);if(symbolValid(i.symbol)){add(Operation::History);p.last().optionalAccountRead=true;}add(Operation::Account);add(Operation::Holdings);if(symbolValid(i.symbol)){add(Operation::Quote);add(Operation::Depth);}return p;}if(kind==BrokerPlanKind::CancelPreflight){add(Operation::OpenOrders);return p;}for(const auto& name:{"managed","halted","liquidation","overheated"}){auto s=directStep(Operation::AssetFilters,i);s.variant=QLatin1String(name);p<<s;}if(!i.orderId.isEmpty())add(Operation::OpenOrders);add(Operation::Account);add(Operation::BuyingPower);add(Operation::Quote);add(Operation::TradingSchedule);add(Operation::Reference);add(Operation::Depth);return p;}
QList<Operation> LsAdapter::refreshPlan()const{return {Operation::OpenOrders,Operation::Account,Operation::Holdings,Operation::Quote,Operation::Depth};}
RequestSpec LsAdapter::build(Operation op,const AccountRecord&,const OrderInput& i,const CredentialSet&,qint64 now,QString* e)const{return buildStep(directStep(op,i),now,e);}
AdapterResult LsAdapter::parse(Operation op,const HttpResult& r,const OrderInput& i)const{return parseStep(directStep(op,i),r).value;}
QString LsAdapter::amendDescription()const{return "미체결 지정가 주문의 현재 잔량을 그대로 유지하고 가격만 변경합니다. 부분체결·수량 변경은 지원하지 않습니다.";}
QByteArray LsAdapter::binding(const BrokerStep& s)const{return digest({identityDomain(IdentityDomain::LsCursor),scope_.toUtf8(),environment_.toUtf8(),QByteArray::number(int(s.operation)),s.variant.toUtf8(),s.catalogMarket.toUtf8(),s.input.symbol.toUtf8(),s.input.side.toUtf8(),s.input.type.toUtf8(),s.input.price.toUtf8(),s.input.quantity.toUtf8(),s.input.orderId.toUtf8(),dateFor(s,clock_()).toUtf8()});}
