 if(!echoed.isEmpty()&&echoed!=tr.toLatin1())return fail("요청한 LS TR과 응답 TR이 다릅니다.");
 if(s.operation==Operation::Authenticate){auto token=str(o,"access_token").toLatin1();auto guard=qScopeGuard([&]{wipe(token);});auto a=str(o,"expire_in"),b=str(o,"expires_in");if(a.isEmpty())a=b;if(!digits(a,1,7)||(!b.isEmpty()&&a!=b)||str(o,"token_type").compare("Bearer",Qt::CaseInsensitive)||str(o,"scope")!="oob"||!QRegularExpression("\\A[A-Za-z0-9._~+/-]+=*\\z").match(QString::fromLatin1(token)).hasMatch()||token.size()>16384)return fail("LS 토큰의 종류·만료 정보를 확인하지 못했습니다.");bool ok=false;const auto secs=a.toLongLong(&ok);if(!ok||secs<=0||secs>604800)return fail();try{token_=SecureBuffer(token.data(),size_t(token.size()));}catch(...){return fail("토큰 보호 메모리를 확보하지 못했습니다.");}lifetimeMs_=secs*1000;tokenAge_.start();r.ok=true;return out;}
