 if(!positive(last)||!positive(low)||!positive(high)||!digits(step)||!positive(step)||!decimal::multipleOf(i.quantity,step)||!decimal::multipleOf(i.price,tick(i.price))||decimal::compare(low,high)>0||decimal::compare(i.price,low)<0||decimal::compare(i.price,high)>0)return deny("LS 가격 제한·호가 단위·수량 단위를 확인해 주세요.");
