  if(count!=1||!match.value("cancelable").toBool()||str(match,"symbol")!=in.symbol||str(match,"side")!=in.side||str(match,"type")!=in.type||!digits(in.quantity,1,16)||!positive(in.quantity)||!num(str(match,"remaining"))||decimal::compare(in.quantity,str(match,"remaining"))!=0||in.quantityMode!=OrderQuantityMode::Exact)return deny("조회한 현재 잔량과 입력 수량이 달라 변경을 준비할 수 없습니다. 새로 조회한 수량을 직접 확인해 주세요.",BrokerNotReady::ChangedInput);
