 const auto* schedule=find(Operation::TradingSchedule,"server-time",10000);const auto* reference=find(Operation::Reference,"krx-minute",10000);const auto* depth=find(Operation::Depth,"krx-depth",10000);
 const auto local=kst(now);if(local.date().dayOfWeek()>5||local.time()<QTime(9,0)||local.time()>=QTime(15,20))return deny("현재 LS 첫 경로는 KRX 평일 정규 연속매매 시간만 지원합니다.");
 if(schedule->sourceTime.quality!=SourceTimeQuality::FullTimestamp||!schedule->sourceTime.fullTimestamp.isValid()||qAbs(schedule->sourceTime.fullTimestamp.msecsTo(now))>10000||dateOf(schedule->sourceTime.fullTimestamp)!=dateOf(now))return deny("LS 공식 서버 날짜·시각과 현재 시각이 일치하지 않습니다.");
