bool LsAdapter::bindRelation(const QString& operation,const QString& target,const QString& root)const{
 if(!selected_||scope_.isEmpty()||!orderReferenceValid(operation)||!orderReferenceValid(target)||!orderReferenceValid(root)||operation==target)return false;
 for(const auto& id:{operation,target,root})if(id.section('_',1,1)!=target.section('_',1,1)||id.section('_',2,2)!="KRX")return false;
 const auto at=relations_.constFind(operation);if(at!=relations_.cend())return at->target==target&&at->root==root;if(relations_.size()>=1000)return false;relations_.insert(operation,{target,root});return true;
}
bool LsAdapter::restoreReconciliationIntent(const QString& kind,const OrderInput& in){return (kind=="cancel"||kind=="amend")&&sessionReady()&&selected_&&in.baseOriginalProvenance==OrderReferenceProvenance::BrokerReceipt&&bindRelation(in.operationOrderId,in.orderId,in.baseOriginalOrderId);}
BrokerReconciliation LsAdapter::reconcile(const QString& kind,const OrderInput& in,const QList<OrderRecord>& orders)const{
 BrokerReconciliation r;r.message="LS 최종 상태를 입증할 상세 조회 증거가 없어 미확정으로 보존합니다.";
 if(!sessionReady()||!selected_||kind!="place")return r;const auto receipt=receipts_.constFind(in.orderId);if(receipt==receipts_.cend()||receipt->scope!=scope_||receipt->date!=dateOf(clock_())||receipt->intent.symbol!=in.symbol||receipt->intent.side!=in.side||receipt->intent.type!=in.type||receipt->intent.clientId!=in.clientId||!num(in.price)||!num(in.quantity)||decimal::compare(receipt->intent.price,in.price)!=0||decimal::compare(receipt->intent.quantity,in.quantity)!=0)return r;
 int count=0;const OrderRecord* match=nullptr;for(const auto& order:orders)if(order.orderId==in.orderId){++count;match=&order;}if(count!=1||!match||!match->cancelable||(match->status!="open"&&match->status!="partial")||match->market!="domestic_equity"||match->symbol!=in.symbol||match->side!=in.side||match->type!=in.type||!num(match->price)||!num(match->quantity)||!num(match->executed)||!num(match->remaining)||decimal::compare(match->price,in.price)!=0||decimal::compare(match->quantity,in.quantity)!=0||decimal::compare(decimal::add(match->executed,match->remaining),in.quantity)!=0)return r;
 r.resolved=true;r.applied=true;r.message="동일 세션 접수증과 미체결 목록이 일치하여 신규 접수를 확인했습니다. 최종 체결을 뜻하지 않습니다.";return r;
}
